def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    decrease_ratio = (old - new) / old
    percentage_decrease = decrease_ratio * 100

    return {
        "value": percentage_decrease,
        "trace": {
            "old_value": old,
            "new_value": new,
            "decrease_ratio": decrease_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
